        return Mockito.any(BugInstance.class);
    }

    public static List<Integer> range(int from, int to) {
        List<Integer> rangeList = new ArrayList<Integer>();
        for(int i=from;i<Math.max(from,to);i++) {
            rangeList.add(i);
        }
        return rangeList;
    }

